#!/usr/bin/env python3
"""HarborPass JSON command-line application."""
import json
import sys
from datetime import date, timedelta


def make_release_1_0_notice(account):
    """Approved release 1.0 values, frozen for support case IOS-1842."""
    credit_cents = 0
    if account["autopay"] and account["completed_years"] >= 2:
        credit_cents = min(account["plan_cents"] // 10, 2400)
    send_on = date.fromisoformat(account["renewal_on"]) - timedelta(days=21)
    return {
        "customer_id": account["customer_id"],
        "send_on": send_on.isoformat(),
        "credit_cents": credit_cents,
        "amount_due_cents": account["plan_cents"] - credit_cents,
    }


def make_notice(account):
    """Current customer-facing policy; future changes belong here."""
    credit_cents = 0
    if account["completed_years"] >= 3:
        credit_cents = min(account["plan_cents"] * 15 // 100, 3600)
    send_on = date.fromisoformat(account["renewal_on"]) - timedelta(days=14)
    return {
        "customer_id": account["customer_id"],
        "send_on": send_on.isoformat(),
        "credit_cents": credit_cents,
        "amount_due_cents": account["plan_cents"] - credit_cents,
    }


def csv_field(value):
    value = str(value)
    if any(character in value for character in ',"\r\n'):
        return '"' + value.replace('"', '""') + '"'
    return value


def export_notices(accounts):
    columns = ("customer_id", "send_on", "credit_cents", "amount_due_cents")
    rows = [",".join(columns)]
    for account in accounts:
        notice = make_notice(account)
        rows.append(",".join(csv_field(notice[column]) for column in columns))
    return {"csv": "\n".join(rows) + "\n", "count": len(accounts)}


def handle(request):
    if request.get("command") == "ping":
        return {"status": "ok", "product": "HarborPass"}
    if request.get("command") == "notice":
        return make_notice(request["account"])
    if request.get("command") == "export":
        return export_notices(request["accounts"])
    if request.get("command") == "support_replay":
        return {
            "case_id": request["case_id"],
            "notice": make_release_1_0_notice(request["account"]),
        }
    return {"error": "unknown_command"}


def main():
    request = json.load(sys.stdin)
    response = handle(request)
    json.dump(response, sys.stdout)
    sys.stdout.write("\n")


if __name__ == "__main__":
    main()
# HarborPass renewal CLI

HarborPass sells annual memberships. This project is a small local JSON application. It requires Python 3.9 or later and no packages or network access.

Run `python3 main.py` with one JSON request on standard input. The program writes one JSON response to standard output. Currently `{"command":"ping"}` returns `{"status":"ok","product":"HarborPass"}`; an unrecognized command returns `{"error":"unknown_command"}`. JSON key order and surrounding JSON whitespace do not matter.

Run the starter tests with `python3 -m unittest discover -s tests -v`. Each product issue is accompanied by a public JSON examples file. Run those examples with `python3 test_public.py --cases /path/to/stage_N.json`. Feature examples for an earlier stage can become obsolete when a later issue explicitly changes its business requirements; the issue history remains available to explain prior releases.

Accounts use customer_id (nonempty string), renewal_on (valid Gregorian YYYY-MM-DD from 2020-01-01 through 2099-12-31), plan_cents (nonnegative integer US cents), completed_years (nonnegative integer), and autopay (boolean). A notice contains customer_id, send_on, credit_cents, and amount_due_cents. Account collections preserve order and duplicate customer IDs. Inputs to the exercises are well formed. No current clock, locale, or remote data is needed.

Send `{"command":"notice","account":ACCOUNT}` to generate a current renewal notice. For every renewal date, the notice is dated 14 calendar days before renewal. Members with at least 3 completed years receive a credit of 15% of their plan price, rounded down to whole cents and capped at 3600 cents. Autopay does not affect eligibility. All other members receive zero credit. The amount due is the plan price minus the credit.

Send `{"command":"export","accounts":[ACCOUNT,...]}` to export the current notices as `{"csv":STRING,"count":N}`. The CSV columns are `customer_id,send_on,credit_cents,amount_due_cents`, with one row per account in input order, including duplicate IDs. The header and each row end with LF, including for an empty collection. Fields are quoted only if they contain a comma, double quote, CR, or LF; internal double quotes are doubled.

Send `{"command":"support_replay","case_id":"IOS-1842","account":ACCOUNT}` to reproduce the approved release 1.0 preview as `{"case_id":"IOS-1842","notice":NOTICE}`. This case always sends notices 21 calendar days before renewal and awards members with autopay enabled and at least 2 completed years a credit of 10% of the plan price, rounded down to whole cents and capped at 2400 cents; other members receive zero credit. The amount due is the plan price minus the credit. These historical rules remain frozen when current notice and export policies change. IOS-1842 is the only supported case.

